<?php
namespace App\Domain\Tax\Services; use App\Models\TaxDocumentSequence; use Illuminate\Support\Facades\DB; class TaxDocumentNumberService { public function next(string $type,?int $vendorId):string{return DB::transaction(/** Inline callback for this operation. */ function()use($type,$vendorId){$year=now()->format('Y');$scope=$type.':'.$year.':'.($vendorId?:'marketplace');$row=TaxDocumentSequence::query()->firstOrCreate(['scope_key'=>$scope],['next_number'=>1]);$row=TaxDocumentSequence::query()->whereKey($row->id)->lockForUpdate()->firstOrFail();$n=(int)$row->next_number;$row->update(['next_number'=>$n+1]);return strtoupper($type).'-'.$year.'-'.($vendorId?:'MKT').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);},3);} }